// Helper function to compare two arrays of floats
int issame(const float* a, int a_count, const float* b, int b_count) {
    if (a_count != b_count) return 0;
    for (int i = 0; i < a_count; i++) {
        if (fabs(a[i] - b[i]) > 1e-4) return 0;
    }
    return 1;
}

